import { createContext, useContext, useEffect, useMemo, useState } from 'react'
import type { ReactNode } from 'react'

export type Theme = 'light' | 'dark'

export const THEME_STORAGE_KEY = 'lumen-theme'

export const chartTheme = {
  light: {
    grid: '#eceff1',
    tick: '#6b7280',
    legend: '#1a1d21',
    series: [
      { border: '#2563eb', fill: 'rgba(37,99,235,0.12)' },
      { border: '#16a34a', fill: 'rgba(22,163,74,0.12)' },
    ],
  },
  dark: {
    grid: '#334155',
    tick: '#94a3b8',
    legend: '#e2e8f0',
    series: [
      { border: '#60a5fa', fill: 'rgba(96,165,250,0.18)' },
      { border: '#34d399', fill: 'rgba(52,211,153,0.18)' },
    ],
  },
} as const

function getInitialTheme(): Theme {
  if (typeof window === 'undefined') return 'light'

  try {
    const raw = localStorage.getItem(THEME_STORAGE_KEY)
    if (raw !== null) {
      const parsed = JSON.parse(raw)
      if (parsed === 'light' || parsed === 'dark') return parsed
    }
  } catch {
    // Ignore unreadable stored values and fall through to system preference.
  }

  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
}

interface ThemeContextValue {
  theme: Theme
  toggleTheme: () => void
}

const ThemeContext = createContext<ThemeContextValue | undefined>(undefined)

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<Theme>(getInitialTheme)

  useEffect(() => {
    document.documentElement.dataset.theme = theme
    try {
      localStorage.setItem(THEME_STORAGE_KEY, JSON.stringify(theme))
    } catch {
      // Ignore write failures (private mode, quota).
    }
  }, [theme])

  // Follow OS-level changes only while the user has not chosen an explicit theme.
  useEffect(() => {
    const mq = window.matchMedia('(prefers-color-scheme: dark)')
    const onChange = (event: MediaQueryListEvent) => {
      let hasStoredTheme = false
      try {
        hasStoredTheme = localStorage.getItem(THEME_STORAGE_KEY) !== null
      } catch {
        hasStoredTheme = false
      }
      if (!hasStoredTheme) {
        setTheme(event.matches ? 'dark' : 'light')
      }
    }

    if (typeof mq.addEventListener === 'function') {
      mq.addEventListener('change', onChange)
      return () => mq.removeEventListener('change', onChange)
    }

    // Safari < 14 fallback.
    if (typeof mq.addListener === 'function') {
      mq.addListener(onChange)
      return () => mq.removeListener(onChange)
    }
  }, [])

  const value = useMemo(
    () => ({
      theme,
      toggleTheme: () => setTheme((current) => (current === 'light' ? 'dark' : 'light')),
    }),
    [theme],
  )

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>
}

export function useTheme(): ThemeContextValue {
  const context = useContext(ThemeContext)
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider')
  }
  return context
}

