import { Line } from 'react-chartjs-2'
import {
  Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement,
  Tooltip, Legend, Filler,
} from 'chart.js'
import { useTheme, chartTheme } from '../theme'

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Tooltip, Legend, Filler)

interface Props {
  labels: string[]
  series: { name: string; data: number[] }[]
}

export default function MetricChart({ labels, series }: Props) {
  const { theme } = useTheme()
  const palette = chartTheme[theme]
  const seriesPalette = palette.series

  const data = {
    labels,
    datasets: series.map((s, i) => ({
      label: s.name,
      data: s.data,
      borderColor: seriesPalette[i]?.border ?? seriesPalette[0].border,
      backgroundColor: seriesPalette[i]?.fill ?? seriesPalette[0].fill,
      fill: true,
      tension: 0.35,
      pointRadius: 2,
    })),
  }
  const options = {
    responsive: true,
    plugins: {
      legend: { labels: { color: palette.legend } },
    },
    scales: {
      x: { ticks: { color: palette.tick }, grid: { color: palette.grid } },
      y: { ticks: { color: palette.tick }, grid: { color: palette.grid } },
    },
  }
  return <div className="chart"><Line data={data} options={options} /></div>
}
