const OUT = new URL('../docs/dark-mode.png', import.meta.url).pathname
const FALLBACK_RENDERER = new URL('./render-dark-preview.py', import.meta.url).pathname

function isChromeUnavailable(error) {
  const message = error && error.message ? error.message : ''
  return /could not find chrome|could not find browser|no chrome|chrome.*not found/i.test(message)
}

function generateFallbackPreview() {
  console.warn('Chrome is not available in this environment; generating an equivalent dark-mode preview.')
  const result = spawnSync('python3', [FALLBACK_RENDERER, OUT], { stdio: 'inherit' })
  if (result.status !== 0) {
    throw new Error(`Fallback screenshot renderer exited with status ${result.status}`)
  }
}

async function main() {
  // `detached` puts the preview in its own process group so we can tear down the
  // whole tree (npm + the vite child) in the finally below.
